import type { RawQ } from "../types";
// ʿAqīda: pillars of īmān and islām, iḥsān, tawḥīd, shirk, the beautiful names and attributes, angels, books, messengers, the Last Day, qadar, īmān, classical creeds and their authors. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "aq-001", s: "aqidah", g: 1, d: 1, t: ["pillars-of-iman", "hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["How many pillars of īmān are listed in the hadith of Jibrīl?", ["Six", "Five", "Four", "Seven"], "In the hadith of Jibrīl the Prophet lists six pillars of faith: belief in Allah, His angels, His books, His messengers, the Last Day and the decree (qadar). Five is the number of the pillars of islām."],
    de: ["Wie viele Säulen des Īmān werden im Hadith von Ǧibrīl genannt?", ["Sechs", "Fünf", "Vier", "Sieben"], "Im Hadith von Ǧibrīl nennt der Prophet sechs Glaubenssäulen: den Glauben an Allah, Seine Engel, Seine Bücher, Seine Gesandten, den Jüngsten Tag und die Vorherbestimmung (qadar). Fünf ist die Zahl der Säulen des Islām."],
    ar: ["كم عدد أركان الإيمان المذكورة في حديث جبريل؟", ["ستة", "خمسة", "أربعة", "سبعة"], "عدّ النبي ﷺ في حديث جبريل أركان الإيمان ستة: الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، أما الخمسة فهي أركان الإسلام."] },

  { id: "aq-002", s: "aqidah", g: 1, d: 1, t: ["pillars-of-islam"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Īmān (Islam is built on five)", tr: ["sunni"],
    en: ["What is the first of the five pillars of islām?", ["The two testimonies of faith", "The five daily prayers", "Fasting in Ramaḍān", "Paying the zakāt"], "The hadith of Ibn ʿUmar on which Islam is built begins with testifying that there is no god but Allah and that Muḥammad is His messenger; prayer, zakāt, fasting and ḥajj follow."],
    de: ["Was ist die erste der fünf Säulen des Islām?", ["Das zweifache Glaubensbekenntnis", "Die fünf täglichen Gebete", "Das Fasten im Ramaḍān", "Die Entrichtung der Zakāt"], "Der Hadith von Ibn ʿUmar über die fünf Grundpfeiler des Islam beginnt mit dem Bezeugen, dass es keinen Gott außer Allah gibt und Muḥammad Sein Gesandter ist; danach folgen Gebet, Zakāt, Fasten und Ḥaǧǧ."],
    ar: ["ما أول أركان الإسلام الخمسة؟", ["الشهادتان", "الصلوات الخمس", "صوم رمضان", "إيتاء الزكاة"], "حديث ابن عمر في بناء الإسلام على خمس يبدأ بشهادة أن لا إله إلا الله وأن محمدًا رسول الله، ثم إقام الصلاة وإيتاء الزكاة والحج وصوم رمضان."] },

  { id: "aq-003", s: "aqidah", g: 1, d: 1, t: ["pillars-of-iman", "pillars-of-islam"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["Which of the following is a pillar of īmān rather than a pillar of islām?", ["Belief in the angels", "Fasting in Ramaḍān", "Paying the zakāt", "Pilgrimage to the House"], "Belief in the angels is one of the six pillars of faith. Fasting, zakāt and ḥajj are among the outward pillars of islām named in the same hadith."],
    de: ["Welches der folgenden ist eine Säule des Īmān und nicht des Islām?", ["Der Glaube an die Engel", "Das Fasten im Ramaḍān", "Die Entrichtung der Zakāt", "Die Pilgerfahrt zum Haus"], "Der Glaube an die Engel gehört zu den sechs Glaubenssäulen. Fasten, Zakāt und Ḥaǧǧ gehören zu den äußeren Säulen des Islām, die im selben Hadith genannt werden."],
    ar: ["أيّ مما يلي من أركان الإيمان لا من أركان الإسلام؟", ["الإيمان بالملائكة", "صوم رمضان", "إيتاء الزكاة", "حج البيت"], "الإيمان بالملائكة ركن من أركان الإيمان الستة، أما الصوم والزكاة والحج فمن أركان الإسلام الظاهرة المذكورة في الحديث نفسه."] },

  { id: "aq-004", s: "aqidah", g: 1, d: 1, t: ["ihsan", "hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["How does the hadith of Jibrīl define iḥsān?", ["Worshipping Allah as though you see Him", "Giving charity beyond the obligatory zakāt", "Being kind to parents and relatives", "Reciting the Quran with beautiful tajwīd"], "The Prophet defined iḥsān as worshipping Allah as though you see Him, and if you do not see Him, then knowing that He sees you. Kindness and charity are fruits of it, but not its definition in this hadith."],
    de: ["Wie definiert der Hadith von Ǧibrīl den Iḥsān?", ["Allah anzubeten, als sähe man Ihn", "Spenden über die Pflicht-Zakāt hinaus", "Güte gegenüber Eltern und Verwandten", "Koranrezitation mit schönem Taǧwīd"], "Der Prophet definierte Iḥsān als Anbetung Allahs, als sähe man Ihn, und wenn man Ihn nicht sieht, so sieht Er einen doch. Güte und Spenden sind Früchte davon, aber nicht die Definition in diesem Hadith."],
    ar: ["كيف عُرّف الإحسان في حديث جبريل؟", ["أن تعبد الله كأنك تراه", "التصدق بما يزيد على الزكاة الواجبة", "البر بالوالدين والأقارب", "تلاوة القرآن بتجويد حسن"], "عرّف النبي ﷺ الإحسان بأن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك؛ أما البر والصدقة فمن ثمراته لا من تعريفه في هذا الحديث."] },

  { id: "aq-005", s: "aqidah", g: 1, d: 2, t: ["hadith-jibril"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)",
    en: ["In Ṣaḥīḥ Muslim, from which Companion does Ibn ʿUmar narrate the hadith of Jibrīl?", ["His father ʿUmar ibn al-Khaṭṭāb", "Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "ʿAbd Allāh ibn Masʿūd"], "At the start of Kitāb al-Īmān in Ṣaḥīḥ Muslim, ʿAbd Allāh ibn ʿUmar narrates the hadith of Jibrīl from his father ʿUmar, who was present when the stranger in white clothes came to the Prophet."],
    de: ["Von welchem Gefährten überliefert Ibn ʿUmar im Ṣaḥīḥ Muslim den Hadith von Ǧibrīl?", ["Von seinem Vater ʿUmar ibn al-Ḫaṭṭāb", "Von Abū Bakr aṣ-Ṣiddīq", "Von ʿAlī ibn Abī Ṭālib", "Von ʿAbdallāh ibn Masʿūd"], "Am Anfang des Kitāb al-Īmān im Ṣaḥīḥ Muslim überliefert ʿAbdallāh ibn ʿUmar den Hadith von Ǧibrīl von seinem Vater ʿUmar, der dabei war, als der Fremde in weißer Kleidung zum Propheten kam."],
    ar: ["عمّن يروي ابنُ عمر حديثَ جبريل في صحيح مسلم؟", ["عن أبيه عمر بن الخطاب", "عن أبي بكر الصديق", "عن علي بن أبي طالب", "عن عبد الله بن مسعود"], "في أول كتاب الإيمان من صحيح مسلم يروي عبد الله بن عمر حديث جبريل عن أبيه عمر، وكان حاضرًا حين جاء الرجل الشديد بياض الثياب إلى النبي ﷺ."] },

  { id: "aq-006", s: "aqidah", g: 1, d: 1, t: ["tawhid"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["sunni"],
    en: ["What does the word tawḥīd mean linguistically?", ["Making one, affirming oneness", "Submitting and obeying", "Believing and trusting", "Purifying and cleansing"], "Tawḥīd is the verbal noun of waḥḥada, to make one or declare one. In creed it means affirming that Allah is one, without partner. Submission is the meaning of islām, and belief that of īmān."],
    de: ["Was bedeutet das Wort Tauḥīd sprachlich?", ["Eins machen, die Einheit bekräftigen", "Sich ergeben und gehorchen", "Glauben und vertrauen", "Reinigen und säubern"], "Tauḥīd ist das Verbalnomen von waḥḥada, eins machen oder für eins erklären. In der Glaubenslehre bedeutet es, zu bekräftigen, dass Allah einer ist, ohne Teilhaber. Ergebung ist die Bedeutung von Islām, Glauben die von Īmān."],
    ar: ["ما معنى التوحيد في اللغة؟", ["جعل الشيء واحدًا والحكم بوحدته", "الاستسلام والانقياد", "التصديق والثقة", "التطهير والتنقية"], "التوحيد مصدر وحّد يوحّد أي جعل الشيء واحدًا أو حكم بأنه واحد، وفي الاصطلاح إفراد الله بما يختص به؛ أما الاستسلام فمعنى الإسلام، والتصديق معنى الإيمان."] },

  { id: "aq-007", s: "aqidah", g: 1, d: 1, t: ["shirk"], src: "Ibn Kathīr, Tafsīr, on 4:48", tr: ["sunni"], v: "4:48",
    en: ["According to the verse shown, which sin does Allah not forgive (for one who dies upon it)?", ["Associating partners with Him", "Neglecting the prayer", "Consuming usury", "Breaking ties of kinship"], "The verse shown states that Allah does not forgive that partners be associated with Him, and forgives what is less than that for whom He wills. Scholars explain this of one who dies upon shirk without repenting."],
    de: ["Welche Sünde vergibt Allah laut dem angezeigten Vers nicht (wenn jemand darauf stirbt)?", ["Ihm Teilhaber beizugesellen", "Das Gebet zu vernachlässigen", "Zinsen zu verzehren", "Verwandtschaftsbande abzubrechen"], "Der angezeigte Vers sagt, dass Allah nicht vergibt, dass Ihm etwas beigesellt wird, und dass Er, wem Er will, vergibt, was geringer ist. Die Gelehrten beziehen dies auf den, der ohne Reue auf Širk stirbt."],
    ar: ["بحسب الآية المعروضة، ما الذنب الذي لا يغفره الله لمن مات عليه؟", ["الشرك به", "ترك الصلاة", "أكل الربا", "قطيعة الرحم"], "تقرر الآية المعروضة أن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء، وحمله العلماء على من مات على الشرك دون توبة."] },

  { id: "aq-008", s: "aqidah", g: 1, d: 2, t: ["shirk"], src: "Ibn Kathīr, Tafsīr, on 31:13", tr: ["sunni"], v: "31:13", w: 13,
    en: ["In the verse shown, Luqmān warns his son against shirk. How does he describe shirk with the highlighted word and the word after it?", ["A tremendous wrong", "A small slip", "A hidden illness", "An old custom"], "Luqmān calls shirk a tremendous ẓulm, a wrong in its highest form, because it places worship where it does not belong. In Ṣaḥīḥ al-Bukhārī the Prophet explained the ẓulm of 6:82 by this verse."],
    de: ["Im angezeigten Vers warnt Luqmān seinen Sohn vor dem Širk. Wie beschreibt er den Širk mit dem hervorgehobenen Wort und dem folgenden?", ["Als gewaltiges Unrecht", "Als kleinen Fehltritt", "Als verborgene Krankheit", "Als alte Sitte"], "Luqmān nennt den Širk ein gewaltiges Unrecht (ẓulm), denn er stellt die Anbetung an einen Ort, an den sie nicht gehört. Im Ṣaḥīḥ al-Buḫārī erklärte der Prophet das Unrecht in 6:82 mit diesem Vers."],
    ar: ["في الآية المعروضة يحذّر لقمانُ ابنَه من الشرك، فبمَ وصفه بالكلمة المظللة وما بعدها؟", ["ظلم عظيم", "زلة صغيرة", "داء خفي", "عادة قديمة"], "وصف لقمان الشرك بأنه ظلم عظيم لأنه وضعٌ للعبادة في غير موضعها، وفسّر النبي ﷺ الظلم في آية الأنعام بهذه الآية كما في صحيح البخاري."] },

  { id: "aq-009", s: "aqidah", g: 1, d: 1, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 2:97–98", tr: ["sunni"],
    en: ["Which angel was entrusted with bringing revelation to the prophets?", ["Jibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Jibrīl is the angel of revelation, called in the Quran the Trustworthy Spirit (26:193). Mīkāʾīl is commonly associated with rain, Isrāfīl with the trumpet, and Mālik is the keeper of Hell."],
    de: ["Welcher Engel ist damit betraut, den Propheten die Offenbarung zu überbringen?", ["Ǧibrīl", "Mīkāʾīl", "Isrāfīl", "Mālik"], "Ǧibrīl ist der Engel der Offenbarung, im Koran der vertrauenswürdige Geist genannt (26:193). Mīkāʾīl wird gewöhnlich mit dem Regen, Isrāfīl mit dem Horn verbunden, und Mālik ist der Hüter der Hölle."],
    ar: ["مَن الملَك الموكَّل بالوحي إلى الأنبياء؟", ["جبريل", "ميكائيل", "إسرافيل", "مالك"], "جبريل هو ملك الوحي، وسمّاه القرآن الروح الأمين (الشعراء 193)، ويُذكر ميكائيل بالقطر، وإسرافيل بالنفخ في الصور، ومالك خازن النار."] },

  { id: "aq-010", s: "aqidah", g: 1, d: 2, t: ["angels"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the creation of the angels", tr: ["sunni"],
    en: ["Which angel is commonly described by the scholars as entrusted with rain and vegetation?", ["Mīkāʾīl", "Jibrīl", "Isrāfīl", "Riḍwān"], "Scholars commonly mention Mīkāʾīl as the angel entrusted with rain and plants. Jibrīl is linked to revelation, which gives life to hearts, and Isrāfīl to the blowing of the trumpet."],
    de: ["Welcher Engel wird von den Gelehrten gewöhnlich als mit Regen und Pflanzenwuchs betraut beschrieben?", ["Mīkāʾīl", "Ǧibrīl", "Isrāfīl", "Riḍwān"], "Die Gelehrten nennen gewöhnlich Mīkāʾīl als den Engel, der mit Regen und Pflanzen betraut ist. Ǧibrīl ist mit der Offenbarung verbunden, die die Herzen belebt, und Isrāfīl mit dem Blasen des Horns."],
    ar: ["أيّ الملائكة يذكره العلماء عادةً موكَّلًا بالقطر والنبات؟", ["ميكائيل", "جبريل", "إسرافيل", "رضوان"], "يذكر العلماء عادةً أن ميكائيل موكّل بالقطر والنبات، وجبريل بالوحي الذي به حياة القلوب، وإسرافيل بالنفخ في الصور."] },

  { id: "aq-011", s: "aqidah", g: 1, d: 1, t: ["angels", "hell"], src: "Ibn Kathīr, Tafsīr, on 43:77", tr: ["sunni"], v: "43:77", w: 2,
    en: ["The people of Hell call out to an angel by name with the highlighted word. Who is he?", ["Mālik, the keeper of Hell", "Riḍwān, the keeper of Paradise", "The angel of death", "Isrāfīl, the blower of the trumpet"], "In the verse shown the people of the Fire call out to Mālik, asking that their Lord put an end to them. Mālik is the keeper of Hell named in the Quran."],
    de: ["Die Bewohner der Hölle rufen mit dem hervorgehobenen Wort einen Engel beim Namen. Wer ist es?", ["Mālik, der Hüter der Hölle", "Riḍwān, der Hüter des Paradieses", "Der Engel des Todes", "Isrāfīl, der das Horn bläst"], "Im angezeigten Vers rufen die Bewohner des Feuers Mālik an und bitten, ihr Herr möge ihrem Dasein ein Ende setzen. Mālik ist der im Koran genannte Hüter der Hölle."],
    ar: ["ينادي أهلُ النار ملَكًا باسمه في الكلمة المظللة، فمن هو؟", ["مالك خازن النار", "رضوان خازن الجنة", "ملك الموت", "إسرافيل صاحب الصور"], "في الآية المعروضة ينادي أهل النار مالكًا يسألونه أن يقضي عليهم ربهم، ومالك هو خازن النار المسمّى في القرآن."] },

  { id: "aq-012", s: "aqidah", g: 1, d: 1, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 4:163 and 5:44–46", tr: ["sunni"],
    en: ["To which prophet was the Tawrāt revealed?", ["Mūsā", "Dāwūd", "ʿĪsā", "Ibrāhīm"], "The Tawrāt was revealed to Mūsā, the Zabūr to Dāwūd and the Injīl to ʿĪsā. The Quran mentions scriptures (ṣuḥuf) of Ibrāhīm as well."],
    de: ["Welchem Propheten wurde die Tora (Tawrāt) offenbart?", ["Mūsā", "Dāwūd", "ʿĪsā", "Ibrāhīm"], "Die Tora wurde Mūsā offenbart, der Psalter (Zabūr) Dāwūd und das Evangelium (Inǧīl) ʿĪsā. Der Koran erwähnt auch Blätter (ṣuḥuf) Ibrāhīms."],
    ar: ["على أيّ نبي أُنزلت التوراة؟", ["موسى", "داود", "عيسى", "إبراهيم"], "أُنزلت التوراة على موسى، والزبور على داود، والإنجيل على عيسى، وذكر القرآن صحف إبراهيم كذلك."] },

  { id: "aq-013", s: "aqidah", g: 1, d: 1, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 4:163", tr: ["sunni"],
    en: ["To which prophet was the Zabūr given?", ["Dāwūd", "Sulaymān", "Mūsā", "Yaḥyā"], "The Quran states that Allah gave Dāwūd the Zabūr (4:163, 17:55). Sulaymān was his son, and Yaḥyā is not associated with a named book."],
    de: ["Welchem Propheten wurde der Psalter (Zabūr) gegeben?", ["Dāwūd", "Sulaimān", "Mūsā", "Yaḥyā"], "Der Koran sagt, dass Allah Dāwūd den Zabūr gab (4:163, 17:55). Sulaimān war sein Sohn, und mit Yaḥyā ist kein namentlich genanntes Buch verbunden."],
    ar: ["على أيّ نبي أُنزل الزبور؟", ["داود", "سليمان", "موسى", "يحيى"], "نصّ القرآن على أن الله آتى داود زبورًا (النساء 163، الإسراء 55)، وسليمان ابنه، ولم يُذكر ليحيى كتاب مسمّى."] },

  { id: "aq-014", s: "aqidah", g: 1, d: 1, t: ["books", "quran-preservation"], src: "Ibn Kathīr, Tafsīr, on 15:9", tr: ["sunni"],
    en: ["Which revealed book has Allah Himself guaranteed to preserve?", ["The Quran", "The Tawrāt", "The Injīl", "The Zabūr"], "In 15:9 Allah says that He sent down the Reminder and will preserve it. The earlier books were entrusted to their communities to guard (5:44) and were not preserved in their original form."],
    de: ["Welches offenbarte Buch hat Allah selbst zu bewahren zugesichert?", ["Den Koran", "Die Tora", "Das Evangelium", "Den Psalter"], "In 15:9 sagt Allah, dass Er die Ermahnung herabgesandt hat und sie bewahren wird. Die früheren Bücher wurden ihren Gemeinschaften zur Bewahrung anvertraut (5:44) und sind nicht in ihrer ursprünglichen Form erhalten."],
    ar: ["أيّ الكتب المنزلة تكفّل الله بنفسه بحفظه؟", ["القرآن", "التوراة", "الإنجيل", "الزبور"], "أخبر الله في سورة الحجر (الآية 9) أنه نزّل الذكر وأنه له حافظ، أما الكتب السابقة فاستُحفظ عليها أهلها (المائدة 44) فلم تبق على أصلها."] },

  { id: "aq-015", s: "aqidah", g: 1, d: 1, t: ["messengers", "finality-of-prophethood"], src: "Ibn Kathīr, Tafsīr, on 33:40", tr: ["ijma"], v: "33:40", w: 11,
    en: ["With the highlighted word and the word after it, how does the verse shown describe the Prophet Muḥammad?", ["As the Seal of the Prophets", "As the first of the messengers", "As the friend of Allah", "As the one spoken to directly"], "The verse calls the Prophet the Seal of the Prophets: no prophet comes after him. This is a matter of consensus; ʿĪsā's return at the end of time does not contradict it, as he was a prophet before."],
    de: ["Wie beschreibt der angezeigte Vers den Propheten Muḥammad mit dem hervorgehobenen Wort und dem folgenden?", ["Als Siegel der Propheten", "Als ersten der Gesandten", "Als Freund Allahs", "Als den, mit dem direkt gesprochen wurde"], "Der Vers nennt den Propheten das Siegel der Propheten: Nach ihm kommt kein Prophet. Darüber besteht Konsens; die Rückkehr ʿĪsās am Ende der Zeit widerspricht dem nicht, da er schon vorher Prophet war."],
    ar: ["بمَ تصف الآية المعروضة النبيَّ محمدًا ﷺ في الكلمة المظللة وما بعدها؟", ["خاتم النبيين", "أول المرسلين", "خليل الله", "كليم الله"], "وصفت الآية النبي ﷺ بأنه خاتم النبيين فلا نبي بعده، وهذا محل إجماع، ونزول عيسى آخر الزمان لا ينافيه لأنه نبي قبله."] },

  { id: "aq-016", s: "aqidah", g: 1, d: 1, t: ["messengers", "divine-speech"], src: "Ibn Kathīr, Tafsīr, on 4:164", tr: ["sunni"], v: "4:164", w: 13,
    en: ["The verse shown states that Allah spoke directly to the prophet named in the highlighted word. Who is he?", ["Mūsā", "Ibrāhīm", "Nūḥ", "ʿĪsā"], "The verse affirms that Allah spoke to Mūsā with real speech, emphasised by the verbal noun after his name. For this he is known as Kalīm Allāh."],
    de: ["Der angezeigte Vers sagt, dass Allah direkt mit dem Propheten sprach, der im hervorgehobenen Wort genannt wird. Wer ist es?", ["Mūsā", "Ibrāhīm", "Nūḥ", "ʿĪsā"], "Der Vers bekräftigt, dass Allah mit Mūsā wirklich sprach, betont durch das Verbalnomen nach seinem Namen. Deshalb ist er als Kalīm Allāh bekannt."],
    ar: ["تذكر الآية المعروضة أن الله كلّم النبيَّ المذكور في الكلمة المظللة تكليمًا، فمن هو؟", ["موسى", "إبراهيم", "نوح", "عيسى"], "أثبتت الآية أن الله كلّم موسى كلامًا حقيقيًا، وأكّده المصدر بعد اسمه، ولذلك لُقّب بكليم الله."] },

  { id: "aq-017", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 6,
    en: ["What does the divine name in the highlighted word mean?", ["The Ever-Living", "The All-Knowing", "The Most Merciful", "The Creator"], "Al-Ḥayy is the Ever-Living, whose life has no beginning and no end and is free of every deficiency. Scholars note that all the attributes of perfection depend on this perfect life."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Ewig-Lebendige", "Der Allwissende", "Der Allbarmherzige", "Der Schöpfer"], "Al-Ḥayy ist der Ewig-Lebendige, dessen Leben weder Anfang noch Ende hat und frei von jedem Mangel ist. Die Gelehrten betonen, dass alle Eigenschaften der Vollkommenheit auf diesem vollkommenen Leben beruhen."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الحي الدائم الحياة", "العليم", "الرحيم", "الخالق"], "الحي هو الذي له الحياة الكاملة التي لا ابتداء لها ولا انتهاء ولا يعتريها نقص، ونبّه العلماء على أن صفات الكمال كلها راجعة إلى كمال الحياة."] },

  { id: "aq-018", s: "aqidah", g: 1, d: 2, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 7,
    en: ["What does the divine name in the highlighted word mean?", ["The Self-Subsisting Sustainer of all", "The Most High above all", "The Forgiving of sins", "The Watcher over all"], "Al-Qayyūm is the One who subsists by Himself, needing nothing, and by whom everything else subsists and is maintained. Al-ʿAliyy (the Most High) comes at the end of the same verse."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der durch sich selbst Bestehende, der alles erhält", "Der Höchste über allem", "Der die Sünden vergibt", "Der über alles wacht"], "Al-Qayyūm ist der, der durch sich selbst besteht, nichts bedarf und durch den alles andere besteht und erhalten wird. Al-ʿAliyy (der Höchste) steht am Ende desselben Verses."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["القائم بنفسه المقيم لغيره", "العلي فوق كل شيء", "الغافر للذنوب", "الرقيب على كل شيء"], "القيوم هو القائم بنفسه الغني عن كل ما سواه، وبه قام كل شيء، أما العلي فقد جاء في آخر الآية نفسها."] },

  { id: "aq-019", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:2", tr: ["sunni"], v: "112:2", w: 2,
    en: ["Which meaning do the exegetes give for the divine name in the highlighted word?", ["The Master to whom all turn in need", "The One who has a son", "The Lord of the dawn", "The Owner of the Throne"], "Al-Ṣamad is explained by Ibn ʿAbbās and others as the Master perfect in His attributes, to whom all creatures turn in their needs, while He needs no one."],
    de: ["Welche Bedeutung geben die Exegeten dem göttlichen Namen im hervorgehobenen Wort?", ["Der Herr, an den sich alle in ihrer Not wenden", "Der, der einen Sohn hat", "Der Herr der Morgendämmerung", "Der Herr des Thrones"], "Aṣ-Ṣamad wird von Ibn ʿAbbās und anderen erklärt als der in Seinen Eigenschaften vollkommene Herr, an den sich alle Geschöpfe in ihren Bedürfnissen wenden, während Er niemanden braucht."],
    ar: ["ما المعنى الذي يذكره المفسرون للاسم الإلهي في الكلمة المظللة؟", ["السيد الذي تصمد إليه الخلائق في حوائجها", "الذي له ولد", "رب الفلق", "صاحب العرش"], "فسّر ابن عباس وغيره الصمد بالسيد الكامل في صفاته الذي تقصده الخلائق في حوائجها وهو غني عنها."] },

  { id: "aq-020", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:1", tr: ["sunni"], v: "112:1", w: 4,
    en: ["What does the highlighted word affirm about Allah?", ["That He is One and unique", "That He is the Most Merciful", "That He is the Most High", "That He is the Creator"], "Aḥad affirms that Allah is one and unique in His essence, attributes and acts, with none like Him. This is why Sūrat al-Ikhlāṣ is the sūra of tawḥīd."],
    de: ["Was bekräftigt das hervorgehobene Wort über Allah?", ["Dass Er der Eine und Einzigartige ist", "Dass Er der Allbarmherzige ist", "Dass Er der Höchste ist", "Dass Er der Schöpfer ist"], "Aḥad bekräftigt, dass Allah in Seinem Wesen, Seinen Eigenschaften und Handlungen einer und einzigartig ist, ohne dass Ihm etwas gleicht. Deshalb ist Sūrat al-Iḫlāṣ die Sure des Tauḥīd."],
    ar: ["ماذا تُثبت الكلمة المظللة لله تعالى؟", ["أنه الواحد المتفرد", "أنه الرحيم", "أنه العلي", "أنه الخالق"], "الأحد يثبت أن الله واحد متفرد في ذاته وصفاته وأفعاله لا نظير له، ولذلك كانت سورة الإخلاص سورة التوحيد."] },

  { id: "aq-021", s: "aqidah", g: 1, d: 2, t: ["surat-al-ikhlas", "tawhid"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb Faḍāʾil al-Qurʾān", tr: ["sunni"],
    en: ["According to the hadith in Ṣaḥīḥ al-Bukhārī, Sūrat al-Ikhlāṣ is equal to what portion of the Quran?", ["A third", "A quarter", "A half", "A tenth"], "The Prophet said that Sūrat al-Ikhlāṣ equals a third of the Quran. Many scholars explain that the Quran deals with rulings, narratives and tawḥīd, and this sūra is devoted entirely to tawḥīd."],
    de: ["Welchem Teil des Korans entspricht Sūrat al-Iḫlāṣ laut dem Hadith im Ṣaḥīḥ al-Buḫārī?", ["Einem Drittel", "Einem Viertel", "Der Hälfte", "Einem Zehntel"], "Der Prophet sagte, dass Sūrat al-Iḫlāṣ einem Drittel des Korans entspricht. Viele Gelehrte erklären, dass der Koran Bestimmungen, Erzählungen und Tauḥīd behandelt und diese Sure ganz dem Tauḥīd gewidmet ist."],
    ar: ["بحسب الحديث في صحيح البخاري، سورة الإخلاص تعدل كم من القرآن؟", ["ثلثه", "ربعه", "نصفه", "عشره"], "أخبر النبي ﷺ أن سورة الإخلاص تعدل ثلث القرآن، وفسّره كثير من العلماء بأن القرآن أحكام وقصص وتوحيد، وهذه السورة خالصة في التوحيد."] },

  { id: "aq-022", s: "aqidah", g: 1, d: 2, t: ["ayat-al-kursi"], src: "Muslim, al-Ṣaḥīḥ, Kitāb Ṣalāt al-Musāfirīn (virtue of Āyat al-Kursī)", tr: ["sunni"], v: "2:255",
    en: ["According to the hadith of Ubayy ibn Kaʿb in Ṣaḥīḥ Muslim, what is special about the verse shown?", ["It is the greatest verse in the Book of Allah", "It was the first verse revealed", "It was the last verse revealed", "It is the longest verse of the Quran"], "The Prophet asked Ubayy which verse of the Book of Allah is greatest, and he named Āyat al-Kursī, and the Prophet praised his knowledge. The longest verse of the Quran is 2:282, not this one."],
    de: ["Was ist laut dem Hadith von Ubayy ibn Kaʿb im Ṣaḥīḥ Muslim das Besondere am angezeigten Vers?", ["Er ist der gewaltigste Vers im Buch Allahs", "Er war der erste offenbarte Vers", "Er war der letzte offenbarte Vers", "Er ist der längste Vers des Korans"], "Der Prophet fragte Ubayy, welcher Vers im Buch Allahs der gewaltigste sei; er nannte den Thronvers, und der Prophet lobte sein Wissen. Der längste Vers des Korans ist 2:282, nicht dieser."],
    ar: ["بحسب حديث أُبيّ بن كعب في صحيح مسلم، ما الذي تختص به الآية المعروضة؟", ["أنها أعظم آية في كتاب الله", "أنها أول ما نزل", "أنها آخر ما نزل", "أنها أطول آية في القرآن"], "سأل النبي ﷺ أُبيًّا عن أعظم آية في كتاب الله فذكر آية الكرسي، فأثنى على علمه، وأطول آية في القرآن آية الدَّين لا هذه."] },

  { id: "aq-023", s: "aqidah", g: 1, d: 1, t: ["barzakh", "last-day"], src: "Ibn al-Qayyim, Kitāb al-Rūḥ, on the barzakh", tr: ["sunni"],
    en: ["What is meant by the barzakh in creed?", ["The stage between death and the resurrection", "The bridge stretched over Hell", "The wall between Paradise and Hell", "The gathering place on the Day of Judgment"], "Barzakh means a barrier; in creed it is the life of the grave between death and resurrection, in which there is bliss or punishment. The bridge is al-Ṣirāṭ and the wall between Paradise and Hell is linked to al-Aʿrāf."],
    de: ["Was ist in der Glaubenslehre mit dem Barzaḫ gemeint?", ["Die Zwischenstufe zwischen Tod und Auferstehung", "Die Brücke über der Hölle", "Die Mauer zwischen Paradies und Hölle", "Der Versammlungsort am Tag des Gerichts"], "Barzaḫ bedeutet Schranke; in der Glaubenslehre ist es das Leben im Grab zwischen Tod und Auferstehung, in dem es Wonne oder Strafe gibt. Die Brücke ist aṣ-Ṣirāṭ, die Mauer zwischen Paradies und Hölle ist mit al-Aʿrāf verbunden."],
    ar: ["ما المقصود بالبرزخ في العقيدة؟", ["المرحلة بين الموت والبعث", "الجسر المنصوب على جهنم", "السور بين الجنة والنار", "موقف الحشر يوم القيامة"], "البرزخ لغة الحاجز، وهو في العقيدة حياة القبر بين الموت والبعث وفيها نعيم أو عذاب، أما الجسر فهو الصراط، والسور بين الجنة والنار متعلق بالأعراف."] },

  { id: "aq-024", s: "aqidah", g: 1, d: 2, t: ["barzakh", "angels"], src: "al-Tirmidhī, al-Jāmiʿ, Kitāb al-Janāʾiz (questioning in the grave)", tr: ["sunni"],
    en: ["By which names are the two angels who question the dead in the grave known, as in a hadith in Jāmiʿ al-Tirmidhī?", ["Munkar and Nakīr", "Hārūt and Mārūt", "Raqīb and ʿAtīd", "Jibrīl and Mīkāʾīl"], "A hadith in al-Tirmidhī names the two questioning angels Munkar and Nakīr. Hārūt and Mārūt are mentioned in 2:102 in connection with Babylon, and Raqīb and ʿAtīd are descriptions of the recording angels in 50:18."],
    de: ["Unter welchen Namen sind die beiden Engel bekannt, die die Toten im Grab befragen, wie in einem Hadith bei at-Tirmiḏī?", ["Munkar und Nakīr", "Hārūt und Mārūt", "Raqīb und ʿAtīd", "Ǧibrīl und Mīkāʾīl"], "Ein Hadith bei at-Tirmiḏī nennt die beiden befragenden Engel Munkar und Nakīr. Hārūt und Mārūt werden in 2:102 im Zusammenhang mit Babylon erwähnt, Raqīb und ʿAtīd sind Beschreibungen der aufzeichnenden Engel in 50:18."],
    ar: ["ما اسما الملكين اللذين يسألان الميت في قبره كما في حديث عند الترمذي؟", ["منكر ونكير", "هاروت وماروت", "رقيب وعتيد", "جبريل وميكائيل"], "سمّى حديث عند الترمذي ملكي السؤال منكرًا ونكيرًا، أما هاروت وماروت فذُكرا في البقرة (102) في شأن بابل، ورقيب وعتيد وصفان للملكين الكاتبين في سورة ق (18)."] },

  { id: "aq-025", s: "aqidah", g: 1, d: 1, t: ["sirat", "last-day"], src: "al-Ṭaḥāwī, al-ʿAqīda al-Ṭaḥāwiyya; Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of the intercession)", tr: ["sunni"],
    en: ["What is al-Ṣirāṭ on the Day of Judgment?", ["A bridge set over Hell that people must cross", "The scale on which deeds are weighed", "The basin from which believers drink", "The book of deeds given to each person"], "Al-Ṣirāṭ is a bridge stretched over Hell; people cross it according to their deeds. The scale is the mīzān, the basin is the ḥawḍ, and the record of deeds is the kitāb."],
    de: ["Was ist aṣ-Ṣirāṭ am Tag des Gerichts?", ["Eine Brücke über der Hölle, die die Menschen überqueren müssen", "Die Waage, auf der die Taten gewogen werden", "Das Becken, aus dem die Gläubigen trinken", "Das Buch der Taten, das jeder erhält"], "Aṣ-Ṣirāṭ ist eine über der Hölle gespannte Brücke, die die Menschen gemäß ihren Taten überqueren. Die Waage ist die Mīzān, das Becken der Ḥauḍ, und die Aufzeichnung der Taten das Buch (kitāb)."],
    ar: ["ما الصراط يوم القيامة؟", ["جسر منصوب على متن جهنم يعبره الناس", "الميزان الذي توزن به الأعمال", "الحوض الذي يشرب منه المؤمنون", "كتاب الأعمال الذي يُعطاه كل إنسان"], "الصراط جسر منصوب على جهنم يمرّ عليه الناس على قدر أعمالهم، أما الميزان فتوزن به الأعمال، والحوض يرده المؤمنون، والكتاب صحيفة الأعمال."] },

  { id: "aq-026", s: "aqidah", g: 1, d: 2, t: ["hawd", "last-day"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Riqāq (on the ḥawḍ)", tr: ["sunni"],
    en: ["What is the ḥawḍ affirmed by Ahl al-Sunna?", ["The Prophet's basin from which his community drinks", "A river flowing beneath the Throne", "The spring that washes the dead", "The well of Zamzam in the Hereafter"], "The ḥawḍ is the basin granted to the Prophet on the Day of Judgment; authentic hadith describe its water as whiter than milk and sweeter than honey, and whoever drinks from it will never thirst again."],
    de: ["Was ist der von Ahl as-Sunna bekräftigte Ḥauḍ?", ["Das Becken des Propheten, aus dem seine Gemeinschaft trinkt", "Ein Fluss, der unter dem Thron fließt", "Die Quelle, die die Toten wäscht", "Der Zamzam-Brunnen im Jenseits"], "Der Ḥauḍ ist das Becken, das dem Propheten am Tag des Gerichts gegeben wird; authentische Hadithe beschreiben sein Wasser als weißer als Milch und süßer als Honig, und wer daraus trinkt, wird nie wieder Durst haben."],
    ar: ["ما الحوض الذي يثبته أهل السنة؟", ["حوض النبي ﷺ الذي ترده أمته", "نهر يجري تحت العرش", "عين يُغسل بها الموتى", "بئر زمزم في الآخرة"], "الحوض هو الحوض المعطى للنبي ﷺ في عرصات القيامة، ووصفت الأحاديث الصحيحة ماءه بأنه أشد بياضًا من اللبن وأحلى من العسل، من شرب منه لم يظمأ بعده أبدًا."] },

  { id: "aq-027", s: "aqidah", g: 1, d: 2, t: ["qadar"], src: "Ibn Kathīr, Tafsīr, on 54:49", tr: ["sunni"], v: "54:49", w: 5,
    en: ["The highlighted word states that Allah created everything with what?", ["With a decree and measure (qadar)", "With a fixed number of days", "With a written covenant", "With the help of the angels"], "The verse states that Allah created everything according to qadar: a measure and decree He determined beforehand. Scholars cite it among the main Quranic proofs of the sixth pillar of faith."],
    de: ["Womit hat Allah laut dem hervorgehobenen Wort alles erschaffen?", ["Nach einem Maß und einer Bestimmung (qadar)", "In einer festen Zahl von Tagen", "Mit einem schriftlichen Bund", "Mit Hilfe der Engel"], "Der Vers sagt, dass Allah alles gemäß dem Qadar erschaffen hat: einem Maß und einer Bestimmung, die Er vorher festgelegt hat. Die Gelehrten nennen ihn unter den wichtigsten Koranbelegen der sechsten Glaubenssäule."],
    ar: ["بمَ خلق الله كل شيء بحسب الكلمة المظللة؟", ["بقدر وتقدير سابق", "في عدد معلوم من الأيام", "بعهد مكتوب", "بمعونة الملائكة"], "تقرر الآية أن الله خلق كل شيء بقدر، أي بتقدير سابق منه، ويذكرها العلماء من أظهر أدلة القرآن على الركن السادس من أركان الإيمان."] },

  { id: "aq-028", s: "aqidah", g: 1, d: 1, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 8,
    en: ["What does the divine name in the highlighted word mean?", ["The King, the Sovereign", "The Most Holy", "The Guardian", "The Compeller"], "Al-Malik is the King who owns and governs all things with complete authority. Al-Quddūs (the Most Holy), al-Muhaymin (the Guardian) and al-Jabbār (the Compeller) follow in the same verse."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der König, der Herrscher", "Der Allheilige", "Der Wächter", "Der Allgewaltige"], "Al-Malik ist der König, der alle Dinge mit vollkommener Macht besitzt und lenkt. Al-Quddūs (der Allheilige), al-Muhaimin (der Wächter) und al-Ǧabbār (der Allgewaltige) folgen im selben Vers."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الملك ذو السلطان التام", "القدوس", "المهيمن", "الجبار"], "الملك هو المالك لكل شيء المتصرف فيه بسلطان تام، أما القدوس والمهيمن والجبار فجاءت بعده في الآية نفسها."] },

  { id: "aq-029", s: "aqidah", g: 1, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:24", tr: ["sunni"], v: "59:24", w: 3,
    en: ["What does the divine name in the highlighted word mean?", ["The Creator who determines all things", "The Fashioner who gives forms", "The Originator who brings into being", "The All-Wise in His decisions"], "Al-Khāliq is the Creator who determines and brings things about. The verse then names al-Bāriʾ (the Originator) and al-Muṣawwir (the Fashioner), and closes with al-ʿAzīz al-Ḥakīm."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Schöpfer, der alle Dinge bestimmt", "Der Gestalter, der die Formen gibt", "Der Erschaffer, der ins Dasein bringt", "Der Allweise in Seinen Entscheidungen"], "Al-Ḫāliq ist der Schöpfer, der die Dinge bestimmt und hervorbringt. Der Vers nennt danach al-Bāriʾ (den Erschaffer) und al-Muṣawwir (den Gestalter) und schließt mit al-ʿAzīz al-Ḥakīm."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["الخالق المقدّر للأشياء", "المصوّر الذي يعطي الصور", "البارئ الموجد", "الحكيم في تدبيره"], "الخالق هو المقدّر الموجد للأشياء، ثم ذكرت الآية البارئ والمصوّر، وختمت بالعزيز الحكيم."] },

  { id: "aq-030", s: "aqidah", g: 2, d: 2, t: ["hadith-jibril", "ihsan"], src: "al-Nawawī, al-Arbaʿūn al-Nawawiyya, hadith 2", tr: ["sunni"],
    en: ["At the end of the hadith of Jibrīl, what did the Prophet say was the purpose of Jibrīl's visit?", ["To teach the people their religion", "To announce the signs of the Hour", "To test the knowledge of ʿUmar", "To bring a new revelation of the Quran"], "The Prophet said that it was Jibrīl, who came to teach the people their religion. Scholars therefore see islām, īmān and iḥsān together as the levels of the whole religion."],
    de: ["Was nannte der Prophet am Ende des Hadith von Ǧibrīl als Zweck seines Besuchs?", ["Den Menschen ihre Religion zu lehren", "Die Zeichen der Stunde anzukündigen", "Das Wissen ʿUmars zu prüfen", "Eine neue Koranoffenbarung zu bringen"], "Der Prophet sagte, es sei Ǧibrīl gewesen, der kam, um die Menschen ihre Religion zu lehren. Deshalb sehen die Gelehrten Islām, Īmān und Iḥsān zusammen als die Stufen der ganzen Religion."],
    ar: ["ماذا ذكر النبي ﷺ في آخر حديث جبريل غرضًا لمجيئه؟", ["أن يعلّم الناس دينهم", "أن يخبر بأشراط الساعة", "أن يختبر علم عمر", "أن ينزل بقرآن جديد"], "قال النبي ﷺ إنه جبريل أتى يعلّم الناس دينهم، ولذلك عدّ العلماء الإسلام والإيمان والإحسان مراتب الدين كله."] },

  { id: "aq-031", s: "aqidah", g: 2, d: 2, t: ["hadith-jibril", "signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["When asked in the hadith of Jibrīl about the time of the Hour, what did the Prophet reply?", ["The one asked knows no more than the one asking", "It will come after a thousand years", "It will come on a Friday in Muḥarram", "Only Jibrīl has been told its time"], "The Prophet answered that the one asked knows no better than the questioner, showing that knowledge of the Hour belongs to Allah alone. He then mentioned some of its signs."],
    de: ["Was antwortete der Prophet im Hadith von Ǧibrīl auf die Frage nach dem Zeitpunkt der Stunde?", ["Der Gefragte weiß darüber nicht mehr als der Fragende", "Sie kommt nach tausend Jahren", "Sie kommt an einem Freitag im Muḥarram", "Nur Ǧibrīl kennt ihre Zeit"], "Der Prophet antwortete, der Gefragte wisse darüber nicht mehr als der Fragende; das Wissen um die Stunde gehört allein Allah. Danach nannte er einige ihrer Zeichen."],
    ar: ["بمَ أجاب النبي ﷺ في حديث جبريل حين سُئل عن وقت الساعة؟", ["ما المسؤول عنها بأعلم من السائل", "تقوم بعد ألف سنة", "تقوم يوم جمعة في المحرم", "لم يُخبَر بوقتها إلا جبريل"], "أجاب النبي ﷺ بأن المسؤول ليس أعلم بها من السائل، فعلم الساعة مما استأثر الله به، ثم ذكر بعض أماراتها."] },

  { id: "aq-032", s: "aqidah", g: 2, d: 3, t: ["hadith-jibril", "signs-of-the-hour"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Īmān (hadith of Jibrīl)", tr: ["sunni"],
    en: ["Which sign of the Hour is mentioned in the hadith of Jibrīl?", ["Barefoot shepherds competing in tall buildings", "The sun rising from the west", "The emergence of the Beast", "The descent of ʿĪsā"], "In the hadith of Jibrīl the Prophet mentions that the slave woman gives birth to her mistress and that barefoot, destitute shepherds compete in constructing tall buildings. The other three are major signs from other hadith."],
    de: ["Welches Zeichen der Stunde wird im Hadith von Ǧibrīl erwähnt?", ["Barfüßige Hirten wetteifern im Bau hoher Gebäude", "Die Sonne geht im Westen auf", "Das Tier kommt hervor", "ʿĪsā steigt herab"], "Im Hadith von Ǧibrīl erwähnt der Prophet, dass die Sklavin ihre Herrin gebärt und barfüßige, mittellose Hirten im Bau hoher Gebäude wetteifern. Die anderen drei sind große Zeichen aus anderen Hadithen."],
    ar: ["أيّ أمارات الساعة ورد في حديث جبريل؟", ["تطاول الحفاة العراة رعاء الشاء في البنيان", "طلوع الشمس من مغربها", "خروج الدابة", "نزول عيسى"], "ذكر النبي ﷺ في حديث جبريل أن تلد الأمة ربتها وأن يتطاول الحفاة العراة العالة رعاء الشاء في البنيان، أما الثلاثة الأخرى فمن العلامات الكبرى في أحاديث أخرى."] },

  { id: "aq-033", s: "aqidah", g: 2, d: 2, t: ["tawhid", "tawhid-categories"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["athari"],
    en: ["In the threefold division of tawḥīd common in the Atharī tradition, what is tawḥīd al-rubūbiyya?", ["Affirming Allah alone as Creator, Owner and Disposer", "Directing all acts of worship to Allah alone", "Affirming Allah's names and attributes", "Following the Prophet alone in religion"], "Tawḥīd al-rubūbiyya is singling Allah out in His acts: creating, owning, providing and governing. Directing worship to Him alone is tawḥīd al-ulūhiyya, and affirming His names and attributes is tawḥīd al-asmāʾ wa-l-ṣifāt."],
    de: ["Was ist in der im atharitischen Lehrstrang üblichen Dreiteilung des Tauḥīd der Tauḥīd ar-rubūbiyya?", ["Allah allein als Schöpfer, Besitzer und Lenker zu bekräftigen", "Alle Gottesdienste allein an Allah zu richten", "Allahs Namen und Eigenschaften zu bekräftigen", "Allein dem Propheten in der Religion zu folgen"], "Tauḥīd ar-rubūbiyya heißt, Allah in Seinen Handlungen einzig zu machen: Erschaffen, Besitzen, Versorgen und Lenken. Die Anbetung allein an Ihn zu richten ist Tauḥīd al-ulūhiyya, Seine Namen und Eigenschaften zu bekräftigen Tauḥīd al-asmāʾ wa-ṣ-ṣifāt."],
    ar: ["في التقسيم الثلاثي للتوحيد المشهور عند الأثرية، ما توحيد الربوبية؟", ["إفراد الله بالخلق والملك والتدبير", "إفراد الله بجميع أنواع العبادة", "إثبات أسماء الله وصفاته", "إفراد النبي ﷺ بالاتباع"], "توحيد الربوبية إفراد الله بأفعاله من الخلق والملك والرزق والتدبير، أما إفراده بالعبادة فتوحيد الألوهية، وإثبات الأسماء والصفات توحيد الأسماء والصفات."] },

  { id: "aq-034", s: "aqidah", g: 2, d: 2, t: ["tawhid", "tawhid-categories"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on tawḥīd", tr: ["athari"],
    en: ["In the same threefold division, what does tawḥīd al-ulūhiyya mean?", ["Directing all worship to Allah alone", "Believing that Allah alone creates", "Affirming that Allah has no beginning", "Believing that Allah alone knows the unseen"], "Tawḥīd al-ulūhiyya (also called tawḥīd al-ʿibāda) is singling Allah out with every act of worship: prayer, supplication, sacrifice, vows, reliance and the like. It is the meaning of the testimony that there is no god but Allah."],
    de: ["Was bedeutet in derselben Dreiteilung der Tauḥīd al-ulūhiyya?", ["Jede Anbetung allein an Allah zu richten", "Zu glauben, dass allein Allah erschafft", "Zu bekräftigen, dass Allah keinen Anfang hat", "Zu glauben, dass allein Allah das Verborgene kennt"], "Tauḥīd al-ulūhiyya (auch Tauḥīd al-ʿibāda) heißt, Allah mit jeder Form der Anbetung allein zu meinen: Gebet, Bittgebet, Opfer, Gelübde, Gottvertrauen und Ähnliches. Das ist die Bedeutung des Bekenntnisses, dass es keinen Gott außer Allah gibt."],
    ar: ["في التقسيم نفسه، ما معنى توحيد الألوهية؟", ["إفراد الله بجميع العبادات", "اعتقاد أن الله وحده الخالق", "إثبات أن الله لا ابتداء له", "اعتقاد أن الله وحده يعلم الغيب"], "توحيد الألوهية ويسمّى توحيد العبادة هو إفراد الله بكل عبادة من صلاة ودعاء وذبح ونذر وتوكل ونحوها، وهو معنى شهادة أن لا إله إلا الله."] },

  { id: "aq-035", s: "aqidah", g: 2, d: 3, t: ["tawhid", "tawhid-categories"], src: "al-Bayjūrī, Tuḥfat al-Murīd sharḥ Jawharat al-Tawḥīd, on waḥdāniyya", tr: ["ashari", "maturidi"],
    en: ["Ashʿarī and Māturīdī texts commonly explain Allah's oneness (waḥdāniyya) as oneness in which three respects?", ["Essence, attributes and acts", "Lordship, worship and names", "Knowledge, power and will", "Speech, hearing and sight"], "Kalām manuals explain waḥdāniyya as oneness in essence (no composition and no second), in attributes (none like His) and in acts (no creator besides Him). The lordship–worship–names scheme is the common Atharī division."],
    de: ["Wie erklären ašʿaritische und māturīditische Texte die Einheit Allahs (waḥdāniyya) üblicherweise, nämlich als Einheit in welchen drei Hinsichten?", ["Wesen, Eigenschaften und Handlungen", "Herrschaft, Anbetung und Namen", "Wissen, Macht und Wille", "Rede, Hören und Sehen"], "Die Kalām-Handbücher erklären die Waḥdāniyya als Einheit im Wesen (keine Zusammensetzung, kein Zweiter), in den Eigenschaften (keine gleichen den Seinen) und in den Handlungen (kein Schöpfer außer Ihm). Das Schema Herrschaft–Anbetung–Namen ist die übliche atharitische Einteilung."],
    ar: ["كيف تشرح كتب الأشاعرة والماتريدية الوحدانية عادةً، أي وحدانية في أيّ ثلاثة أمور؟", ["في الذات والصفات والأفعال", "في الربوبية والألوهية والأسماء", "في العلم والقدرة والإرادة", "في الكلام والسمع والبصر"], "تشرح كتب الكلام الوحدانية بأنها وحدانية الذات فلا تركيب ولا ثاني، ووحدانية الصفات فلا مثيل لصفاته، ووحدانية الأفعال فلا خالق سواه، أما تقسيم الربوبية والألوهية والأسماء فهو التقسيم المشهور عند الأثرية."] },

  { id: "aq-036", s: "aqidah", g: 2, d: 2, t: ["shirk", "minor-shirk"], src: "Aḥmad, al-Musnad, hadith of Maḥmūd ibn Labīd (the minor shirk)", tr: ["sunni"],
    en: ["What did the Prophet call \"the minor shirk\", which he feared most for his community?", ["Showing off in worship (riyāʾ)", "Praying to idols", "Denying the Last Day", "Swearing falsely in trade"], "In the hadith of Maḥmūd ibn Labīd in the Musnad, the Prophet said what he feared most for them was the minor shirk, and when asked, he said it is riyāʾ: doing a deed of worship to be seen by people."],
    de: ["Was nannte der Prophet „den kleinen Širk“, den er für seine Gemeinschaft am meisten fürchtete?", ["Das Zur-Schau-Stellen im Gottesdienst (riyāʾ)", "Das Beten zu Götzen", "Das Leugnen des Jüngsten Tages", "Das falsche Schwören im Handel"], "Im Hadith von Maḥmūd ibn Labīd im Musnad sagte der Prophet, er fürchte für sie am meisten den kleinen Širk; auf Nachfrage sagte er, es sei Riyāʾ: eine gottesdienstliche Handlung zu verrichten, um von Menschen gesehen zu werden."],
    ar: ["ما الذي سمّاه النبي ﷺ «الشرك الأصغر» وكان أخوف ما يخافه على أمته؟", ["الرياء في العبادة", "دعاء الأصنام", "إنكار اليوم الآخر", "الحلف الكاذب في البيع"], "في حديث محمود بن لبيد في المسند أخبر النبي ﷺ أن أخوف ما يخاف عليهم الشرك الأصغر، فلما سُئل عنه قال: الرياء، وهو أن يعمل العبادة ليراه الناس."] },

  { id: "aq-037", s: "aqidah", g: 2, d: 3, t: ["shirk", "minor-shirk"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on shirk", tr: ["sunni"],
    en: ["What is the main difference between major and minor shirk according to the scholars?", ["Major shirk takes one out of Islam; minor shirk does not by itself", "Minor shirk is in the heart; major shirk only on the tongue", "Major shirk is forgiven by good deeds; minor is not", "Minor shirk concerns other religions; major concerns Muslims"], "Major shirk, such as worshipping other than Allah, takes a person out of Islam and is not forgiven if one dies upon it. Minor shirk, such as slight riyāʾ, is a grave sin and a means to major shirk, but does not by itself remove one from Islam."],
    de: ["Was ist laut den Gelehrten der Hauptunterschied zwischen großem und kleinem Širk?", ["Großer Širk führt aus dem Islam; kleiner Širk für sich allein nicht", "Kleiner Širk ist im Herzen, großer nur auf der Zunge", "Großer Širk wird durch gute Taten getilgt, kleiner nicht", "Kleiner Širk betrifft andere Religionen, großer die Muslime"], "Großer Širk, etwa die Anbetung von etwas außer Allah, führt aus dem Islam und wird nicht vergeben, wenn man darauf stirbt. Kleiner Širk, etwa ein wenig Riyāʾ, ist eine schwere Sünde und ein Weg zum großen, führt aber für sich allein nicht aus dem Islam."],
    ar: ["ما الفرق الأساسي بين الشرك الأكبر والأصغر عند العلماء؟", ["الأكبر يخرج من الملة والأصغر لا يخرج بذاته", "الأصغر في القلب والأكبر باللسان فقط", "الأكبر تكفّره الحسنات والأصغر لا", "الأصغر في سائر الأديان والأكبر في المسلمين"], "الشرك الأكبر كعبادة غير الله يخرج من الملة ولا يُغفر لمن مات عليه، والأصغر كيسير الرياء كبيرة من الكبائر ووسيلة إلى الأكبر لكنه لا يخرج من الملة بذاته."] },

  { id: "aq-038", s: "aqidah", g: 2, d: 3, t: ["shirk", "tawhid"], src: "al-Tirmidhī, al-Jāmiʿ, Kitāb al-Daʿawāt (supplication is worship)", tr: ["sunni"],
    en: ["Which hadith, narrated by al-Nuʿmān ibn Bashīr in the Sunan, shows that supplication must be directed to Allah alone?", ["Supplication is worship", "Actions are by intentions", "The religion is sincere counsel", "Leave what makes you doubt"], "The Prophet said that supplication is worship and then recited 40:60. Since duʿāʾ is worship, directing it to anyone besides Allah contradicts tawḥīd al-ʿibāda."],
    de: ["Welcher Hadith, überliefert von an-Nuʿmān ibn Bašīr in den Sunan, zeigt, dass das Bittgebet allein an Allah zu richten ist?", ["Das Bittgebet ist Anbetung", "Die Taten gelten nach den Absichten", "Die Religion ist aufrichtiger Rat", "Das Meiden dessen, was Zweifel weckt"], "Der Prophet sagte, das Bittgebet sei Anbetung, und rezitierte dann 40:60. Da Duʿāʾ Anbetung ist, widerspricht es dem Tauḥīd der Anbetung, es an jemand anderen als Allah zu richten."],
    ar: ["أيّ حديث يرويه النعمان بن بشير في السنن يدل على أن الدعاء لا يُصرف إلا لله؟", ["الدعاء هو العبادة", "إنما الأعمال بالنيات", "الدين النصيحة", "دع ما يريبك"], "قال النبي ﷺ: الدعاء هو العبادة، ثم تلا آية غافر (60)، فإذا كان الدعاء عبادة كان صرفه لغير الله منافيًا لتوحيد العبادة."] },

  { id: "aq-039", s: "aqidah", g: 2, d: 2, t: ["beautiful-names"], src: "Ibn Kathīr, Tafsīr, on 7:180", tr: ["sunni"], v: "7:180",
    en: ["What does the verse shown instruct the believers to do with Allah's beautiful names?", ["To call upon Him by them", "To write them on their homes", "To count them on their fingers", "To keep them secret from others"], "The verse states that the most beautiful names belong to Allah and commands that He be called upon by them, and warns against those who deviate regarding His names."],
    de: ["Wozu fordert der angezeigte Vers die Gläubigen in Bezug auf Allahs schönste Namen auf?", ["Ihn mit ihnen anzurufen", "Sie an ihre Häuser zu schreiben", "Sie an den Fingern abzuzählen", "Sie vor anderen geheim zu halten"], "Der Vers sagt, dass Allah die schönsten Namen gehören, befiehlt, Ihn mit ihnen anzurufen, und warnt vor denen, die bei Seinen Namen abweichen."],
    ar: ["بمَ تأمر الآية المعروضة المؤمنين في شأن أسماء الله الحسنى؟", ["أن يدعوه بها", "أن يكتبوها على بيوتهم", "أن يعدّوها على أصابعهم", "أن يكتموها عن الناس"], "تقرر الآية أن لله الأسماء الحسنى وتأمر بدعائه بها، وتحذّر من الذين يلحدون في أسمائه."] },

  { id: "aq-040", s: "aqidah", g: 2, d: 2, t: ["beautiful-names"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tawḥīd (Allah has ninety-nine names)", tr: ["sunni"],
    en: ["According to the hadith of Abū Hurayra in al-Bukhārī and Muslim, whoever does what with Allah's ninety-nine names enters Paradise?", ["Whoever enumerates (aḥṣā) them", "Whoever writes them down", "Whoever hangs them in his house", "Whoever hears them once"], "The hadith says that Allah has ninety-nine names, one hundred less one, and whoever enumerates them (aḥṣāhā) enters Paradise. Scholars explain this as learning them, understanding their meanings and acting by them."],
    de: ["Wer tritt laut dem Hadith von Abū Huraira bei al-Buḫārī und Muslim ins Paradies, in Bezug auf Allahs neunundneunzig Namen?", ["Wer sie erfasst (aḥṣā)", "Wer sie aufschreibt", "Wer sie in seinem Haus aufhängt", "Wer sie einmal hört"], "Der Hadith sagt, dass Allah neunundneunzig Namen hat, hundert weniger einen, und wer sie erfasst (aḥṣāhā), ins Paradies eintritt. Die Gelehrten erklären dies als Lernen der Namen, Verstehen ihrer Bedeutungen und Handeln danach."],
    ar: ["بحسب حديث أبي هريرة في الصحيحين، مَن الذي يدخل الجنة في شأن أسماء الله التسعة والتسعين؟", ["من أحصاها", "من كتبها", "من علّقها في بيته", "من سمعها مرة"], "في الحديث أن لله تسعة وتسعين اسمًا مائة إلا واحدًا من أحصاها دخل الجنة، وفسّر العلماء الإحصاء بحفظها وفهم معانيها والعمل بمقتضاها."] },

  { id: "aq-041", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 9,
    en: ["What does the divine name in the highlighted word mean?", ["The Most Holy, free of every imperfection", "The Source of peace and safety", "The Guardian over all things", "The Supreme in greatness"], "Al-Quddūs is the One utterly pure and free from every deficiency and fault, deserving every praise. Al-Salām, which follows, is often explained as the One free of defects and the source of safety."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Allheilige, frei von jedem Mangel", "Die Quelle des Friedens und der Sicherheit", "Der Wächter über alle Dinge", "Der in Größe Erhabene"], "Al-Quddūs ist der völlig Reine, frei von jedem Mangel und Fehler, dem jedes Lob gebührt. As-Salām, das folgt, wird oft als der Makellose und die Quelle der Sicherheit erklärt."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["المنزّه المطهّر عن كل نقص", "مصدر السلام والأمان", "المهيمن على كل شيء", "المتعالي في عظمته"], "القدوس هو الطاهر المنزه عن كل نقص وعيب المستحق لكل ثناء، والسلام بعده يُفسَّر غالبًا بالسالم من العيوب الذي منه السلامة."] },

  { id: "aq-042", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:23", tr: ["sunni"], v: "59:23", w: 12,
    en: ["Which meaning do the exegetes give for the divine name in the highlighted word?", ["The Witness and Guardian over His creation", "The One who grants security", "The Mighty who is never overcome", "The One who mends what is broken"], "Al-Muhaymin is explained by Ibn ʿAbbās and others as the Witness over the deeds of His creatures, watching and guarding them. Granting security belongs to al-Muʾmin just before it, and might to al-ʿAzīz after it."],
    de: ["Welche Bedeutung geben die Exegeten dem göttlichen Namen im hervorgehobenen Wort?", ["Der Zeuge und Wächter über Seine Schöpfung", "Der Sicherheit gewährt", "Der Mächtige, der nie besiegt wird", "Der heilt, was zerbrochen ist"], "Al-Muhaimin wird von Ibn ʿAbbās und anderen als Zeuge über die Taten Seiner Geschöpfe erklärt, der sie beobachtet und behütet. Sicherheit zu gewähren gehört zu al-Muʾmin direkt davor, Macht zu al-ʿAzīz danach."],
    ar: ["ما المعنى الذي يذكره المفسرون للاسم الإلهي في الكلمة المظللة؟", ["الشاهد الرقيب على خلقه", "الذي يمنح الأمن", "الغالب الذي لا يُغلب", "الذي يجبر الكسير"], "فسّر ابن عباس وغيره المهيمن بالشاهد على أعمال خلقه الرقيب الحافظ لها، أما منح الأمن فمن معنى المؤمن قبله، والغلبة من معنى العزيز بعده."] },

  { id: "aq-043", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:22", tr: ["sunni"], v: "59:22", w: 8,
    en: ["The highlighted word and the two after it describe Allah as the Knower of what?", ["The unseen and the witnessed", "The past and the future", "The heavens and the earth", "The hearts and the tongues"], "The verse describes Allah as the Knower of the ghayb and the shahāda: what is hidden from creatures and what they perceive. Nothing in either realm is hidden from Him."],
    de: ["Das hervorgehobene Wort und die zwei folgenden beschreiben Allah als Kenner wovon?", ["Des Verborgenen und des Offenbaren", "Der Vergangenheit und der Zukunft", "Der Himmel und der Erde", "Der Herzen und der Zungen"], "Der Vers beschreibt Allah als Kenner des Ġaib und der Šahāda: dessen, was den Geschöpfen verborgen ist, und dessen, was sie wahrnehmen. Nichts in beiden Bereichen ist Ihm verborgen."],
    ar: ["تصف الكلمة المظللة وما بعدها الله بأنه عالم ماذا؟", ["الغيب والشهادة", "الماضي والمستقبل", "السماوات والأرض", "القلوب والألسنة"], "وصفت الآية الله بأنه عالم الغيب والشهادة، أي ما غاب عن الخلق وما شاهدوه، فلا يخفى عليه شيء في العالمين."] },

  { id: "aq-044", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "names-59-22-24"], src: "Ibn Kathīr, Tafsīr, on 59:24", tr: ["sunni"], v: "59:24", w: 5,
    en: ["What does the divine name in the highlighted word mean?", ["The Fashioner who gives each thing its form", "The Creator who determines measures", "The Originator who brings into being", "The Mighty, the Invincible"], "Al-Muṣawwir is the One who gives every creature its particular shape and form. Scholars describe the sequence of the verse as determining (al-Khāliq), bringing into being (al-Bāriʾ) and forming (al-Muṣawwir)."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Gestalter, der jedem Ding seine Form gibt", "Der Schöpfer, der die Maße bestimmt", "Der Erschaffer, der ins Dasein bringt", "Der Mächtige, der Unbesiegbare"], "Al-Muṣawwir ist der, der jedem Geschöpf seine besondere Gestalt und Form gibt. Die Gelehrten beschreiben die Abfolge des Verses als Bestimmen (al-Ḫāliq), Ins-Dasein-Bringen (al-Bāriʾ) und Formen (al-Muṣawwir)."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["المصوّر الذي يعطي كل شيء صورته", "الخالق المقدّر", "البارئ الموجد", "العزيز الغالب"], "المصوّر هو الذي يعطي كل مخلوق صورته وهيئته الخاصة، ويذكر العلماء ترتيب الآية: التقدير (الخالق) ثم الإيجاد (البارئ) ثم التصوير (المصوّر)."] },

  { id: "aq-045", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 42,
    en: ["According to the verse shown, what of Allah's encompasses the heavens and the earth (highlighted word)?", ["His Kursī", "His Throne", "His Tablet", "His Pen"], "The verse states that His Kursī extends over the heavens and the earth, which is why it is called Āyat al-Kursī. Many scholars distinguish the Kursī from the Throne (ʿArsh), which is greater still."],
    de: ["Was von Allah umfasst laut dem angezeigten Vers die Himmel und die Erde (hervorgehobenes Wort)?", ["Sein Kursī (Schemel)", "Sein Thron", "Seine Tafel", "Seine Feder"], "Der Vers sagt, dass Sein Kursī die Himmel und die Erde umfasst; daher heißt er Thronvers (Āyat al-Kursī). Viele Gelehrte unterscheiden den Kursī vom Thron (ʿArš), der noch gewaltiger ist."],
    ar: ["بحسب الآية المعروضة، ما الذي وسع السماوات والأرض (الكلمة المظللة)؟", ["كرسيه", "عرشه", "لوحه", "قلمه"], "تذكر الآية أن كرسيه وسع السماوات والأرض، ولذلك سُمّيت آية الكرسي، وكثير من العلماء يفرّقون بين الكرسي والعرش الذي هو أعظم منه."] },

  { id: "aq-046", s: "aqidah", g: 2, d: 2, t: ["beautiful-names", "ayat-al-kursi"], src: "Ibn Kathīr, Tafsīr, on 2:255", tr: ["sunni"], v: "2:255", w: 49,
    en: ["What does the divine name in the highlighted word mean?", ["The Most High", "The Magnificent", "The Ever-Living", "The Most Generous"], "Al-ʿAliyy is the Most High, exalted in rank, in power and above His creation. Al-ʿAẓīm (the Magnificent) is the name that closes the verse right after it."],
    de: ["Was bedeutet der göttliche Name im hervorgehobenen Wort?", ["Der Höchste", "Der Gewaltige", "Der Ewig-Lebendige", "Der Freigebigste"], "Al-ʿAliyy ist der Höchste, erhaben an Rang, an Macht und über Seiner Schöpfung. Al-ʿAẓīm (der Gewaltige) ist der Name, der den Vers direkt danach abschließt."],
    ar: ["ما معنى الاسم الإلهي في الكلمة المظللة؟", ["العلي", "العظيم", "الحي", "الأكرم"], "العلي ذو العلو في قدره وقهره وفوق خلقه، والعظيم هو الاسم الذي خُتمت به الآية بعده مباشرة."] },

  { id: "aq-047", s: "aqidah", g: 2, d: 3, t: ["beautiful-names", "surat-al-ikhlas"], src: "Ibn Kathīr, Tafsīr, on 112:4", tr: ["sunni"], v: "112:4", w: 4,
    en: ["What does the highlighted word negate of Allah?", ["Any equal or peer", "Any beginning in time", "Any need for sleep", "Any limit to His knowledge"], "Kufuw means an equal or match. The verse negates that anyone is comparable to Allah, completing the sūra's affirmation of His oneness and His freedom from begetting and being begotten."],
    de: ["Was verneint das hervorgehobene Wort in Bezug auf Allah?", ["Jeden Gleichen oder Ebenbürtigen", "Jeden zeitlichen Anfang", "Jedes Bedürfnis nach Schlaf", "Jede Grenze Seines Wissens"], "Kufuw bedeutet ein Gleicher oder Ebenbürtiger. Der Vers verneint, dass irgendjemand Allah gleichkommt, und vollendet so die Bekräftigung Seiner Einheit und dass Er weder zeugt noch gezeugt wurde."],
    ar: ["ماذا تنفي الكلمة المظللة عن الله تعالى؟", ["الكفء والنظير", "الابتداء في الزمن", "الحاجة إلى النوم", "حدًّا لعلمه"], "الكفء هو المثيل والنظير، فالآية تنفي أن يكون لله مكافئ، وبها تتم السورة في إثبات وحدانيته ونفي الولد والوالد عنه."] },

  { id: "aq-048", s: "aqidah", g: 2, d: 2, t: ["angels"], src: "Muslim, al-Ṣaḥīḥ, Kitāb al-Zuhd (creation of angels from light)", tr: ["sunni"],
    en: ["According to the hadith of ʿĀʾisha in Ṣaḥīḥ Muslim, from what were the angels created?", ["From light", "From smokeless fire", "From clay", "From water"], "The hadith states that the angels were created from light, the jinn from a smokeless flame of fire, and Ādam from what has been described (clay)."],
    de: ["Woraus wurden die Engel laut dem Hadith von ʿĀʾiša im Ṣaḥīḥ Muslim erschaffen?", ["Aus Licht", "Aus rauchlosem Feuer", "Aus Lehm", "Aus Wasser"], "Der Hadith sagt, dass die Engel aus Licht erschaffen wurden, die Dschinn aus einer rauchlosen Feuerflamme und Ādam aus dem, was beschrieben wurde (Lehm)."],
    ar: ["بحسب حديث عائشة في صحيح مسلم، مِمَّ خُلقت الملائكة؟", ["من نور", "من مارج من نار", "من طين", "من ماء"], "في الحديث أن الملائكة خُلقت من نور، والجان من مارج من نار، وآدم مما وُصف لكم أي من طين."] },

  { id: "aq-049", s: "aqidah", g: 2, d: 2, t: ["angels", "jinn"], src: "Ibn Kathīr, Tafsīr, on 18:50", tr: ["sunni"], v: "18:50",
    en: ["According to the verse shown, to which kind of creation did Iblīs belong?", ["The jinn", "The angels", "The humans", "The beasts"], "The verse states explicitly that Iblīs was of the jinn and departed from his Lord's command. Angels do not disobey Allah (66:6), which is one reason scholars distinguish him from them."],
    de: ["Zu welcher Art von Geschöpfen gehörte Iblīs laut dem angezeigten Vers?", ["Zu den Dschinn", "Zu den Engeln", "Zu den Menschen", "Zu den Tieren"], "Der Vers sagt ausdrücklich, dass Iblīs zu den Dschinn gehörte und sich dem Befehl seines Herrn widersetzte. Engel widersetzen sich Allah nicht (66:6), was ein Grund ist, weshalb die Gelehrten ihn von ihnen unterscheiden."],
    ar: ["بحسب الآية المعروضة، إلى أيّ صنف من الخلق كان إبليس؟", ["الجن", "الملائكة", "الإنس", "البهائم"], "نصّت الآية على أن إبليس كان من الجن ففسق عن أمر ربه، والملائكة لا يعصون الله (التحريم 6)، وهذا من أسباب تفريق العلماء بينه وبينهم."] },

  { id: "aq-050", s: "aqidah", g: 2, d: 3, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 2:102", tr: ["sunni"], v: "2:102",
    en: ["Which two angels are named in the verse shown, in connection with Babylon?", ["Hārūt and Mārūt", "Munkar and Nakīr", "Jibrīl and Mīkāʾīl", "Raqīb and ʿAtīd"], "The verse mentions what was sent down to the two angels in Babylon, Hārūt and Mārūt, who warned that they were only a trial. Jibrīl and Mīkāʾīl are named together in 2:98."],
    de: ["Welche zwei Engel werden im angezeigten Vers im Zusammenhang mit Babylon genannt?", ["Hārūt und Mārūt", "Munkar und Nakīr", "Ǧibrīl und Mīkāʾīl", "Raqīb und ʿAtīd"], "Der Vers erwähnt, was auf die beiden Engel in Babylon, Hārūt und Mārūt, herabgesandt wurde, die warnten, sie seien nur eine Prüfung. Ǧibrīl und Mīkāʾīl werden zusammen in 2:98 genannt."],
    ar: ["ما اسما الملكين المذكورين في الآية المعروضة في شأن بابل؟", ["هاروت وماروت", "منكر ونكير", "جبريل وميكائيل", "رقيب وعتيد"], "تذكر الآية ما أُنزل على الملكين ببابل هاروت وماروت، وكانا يحذّران بأنهما فتنة، أما جبريل وميكائيل فذُكرا معًا في البقرة (98)."] },

  { id: "aq-051", s: "aqidah", g: 2, d: 3, t: ["angels"], src: "Ibn Kathīr, Tafsīr, on 32:11", tr: ["sunni"], v: "32:11",
    en: ["By what title does the verse shown refer to the angel who takes the souls?", ["The angel of death", "The keeper of the Fire", "The Trustworthy Spirit", "The noble scribe"], "The Quran calls him malak al-mawt, the angel of death. The name ʿAzrāʾīl is widespread among Muslims, but scholars note that it is not found in the Quran or in an authentic hadith."],
    de: ["Mit welchem Titel bezeichnet der angezeigte Vers den Engel, der die Seelen nimmt?", ["Der Engel des Todes", "Der Hüter des Feuers", "Der vertrauenswürdige Geist", "Der edle Schreiber"], "Der Koran nennt ihn malak al-maut, den Engel des Todes. Der Name ʿAzrāʾīl ist unter Muslimen verbreitet, doch die Gelehrten weisen darauf hin, dass er weder im Koran noch in einem authentischen Hadith vorkommt."],
    ar: ["بأيّ لقب تذكر الآية المعروضة الملَك الذي يقبض الأرواح؟", ["ملك الموت", "خازن النار", "الروح الأمين", "الكاتب الكريم"], "سمّاه القرآن ملك الموت، واسم عزرائيل شائع بين المسلمين لكن العلماء ينبّهون على أنه لم يرد في القرآن ولا في حديث صحيح."] },

  { id: "aq-052", s: "aqidah", g: 2, d: 2, t: ["books"], src: "Ibn Kathīr, Tafsīr, on 87:18–19", tr: ["sunni"], v: "87:19",
    en: ["The verse shown mentions the scriptures (ṣuḥuf) of which two prophets?", ["Ibrāhīm and Mūsā", "Nūḥ and Ibrāhīm", "Dāwūd and Sulaymān", "Mūsā and ʿĪsā"], "Sūrat al-Aʿlā closes by referring to the earlier scriptures, the ṣuḥuf of Ibrāhīm and Mūsā. Belief in the books includes believing in every book Allah revealed, named or unnamed."],
    de: ["Der angezeigte Vers erwähnt die Blätter (ṣuḥuf) welcher zwei Propheten?", ["Ibrāhīm und Mūsā", "Nūḥ und Ibrāhīm", "Dāwūd und Sulaimān", "Mūsā und ʿĪsā"], "Sūrat al-Aʿlā schließt mit dem Verweis auf die früheren Schriften, die Blätter Ibrāhīms und Mūsās. Der Glaube an die Bücher umfasst jedes von Allah offenbarte Buch, ob namentlich genannt oder nicht."],
    ar: ["تذكر الآية المعروضة صحف أيّ نبيين؟", ["إبراهيم وموسى", "نوح وإبراهيم", "داود وسليمان", "موسى وعيسى"], "خُتمت سورة الأعلى بذكر الصحف الأولى صحف إبراهيم وموسى، والإيمان بالكتب يشمل كل كتاب أنزله الله سُمّي لنا أو لم يُسمَّ."] },

  { id: "aq-053", s: "aqidah", g: 2, d: 2, t: ["messengers", "prophet-and-messenger"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on prophethood", tr: ["sunni"],
    en: ["Which statement reflects the common view on the relation between nabī (prophet) and rasūl (messenger)?", ["Every messenger is a prophet, but not every prophet is a messenger", "Every prophet is a messenger, but not every messenger is a prophet", "The two words always mean exactly the same", "A messenger is an angel, a prophet a human"], "Most scholars hold that rasūl is more specific: every messenger is a prophet, but not every prophet is a messenger. They differ on the exact criterion, for example being sent with a new law or to a people who reject."],
    de: ["Welche Aussage gibt die verbreitete Ansicht über das Verhältnis von Nabī (Prophet) und Rasūl (Gesandter) wieder?", ["Jeder Gesandte ist ein Prophet, aber nicht jeder Prophet ein Gesandter", "Jeder Prophet ist ein Gesandter, aber nicht jeder Gesandte ein Prophet", "Beide Wörter bedeuten immer genau dasselbe", "Ein Gesandter ist ein Engel, ein Prophet ein Mensch"], "Die meisten Gelehrten sehen Rasūl als den engeren Begriff: Jeder Gesandte ist ein Prophet, aber nicht jeder Prophet ein Gesandter. Über das genaue Kriterium gibt es Unterschiede, etwa die Sendung mit einem neuen Gesetz oder zu einem ablehnenden Volk."],
    ar: ["أيّ العبارات تعبّر عن القول المشهور في العلاقة بين النبي والرسول؟", ["كل رسول نبي وليس كل نبي رسولًا", "كل نبي رسول وليس كل رسول نبيًّا", "اللفظان مترادفان دائمًا", "الرسول ملَك والنبي بشر"], "الجمهور على أن الرسول أخص: فكل رسول نبي وليس كل نبي رسولًا، واختلفوا في ضابط الفرق كالإرسال بشرع جديد أو إلى قوم مخالفين."] },

  { id: "aq-054", s: "aqidah", g: 2, d: 2, t: ["messengers"], src: "Ibn Kathīr, Qaṣaṣ al-Anbiyāʾ, introduction", tr: ["sunni"],
    en: ["How many prophets and messengers are commonly counted as named in the Quran?", ["Twenty-five", "Nineteen", "Thirty-three", "Twelve"], "Scholars commonly count twenty-five prophets named in the Quran, eighteen of them in 6:83–86. The Quran states that there are others not narrated to the Prophet (4:164)."],
    de: ["Wie viele Propheten und Gesandte werden gewöhnlich als im Koran namentlich genannt gezählt?", ["Fünfundzwanzig", "Neunzehn", "Dreiunddreißig", "Zwölf"], "Die Gelehrten zählen gewöhnlich fünfundzwanzig im Koran genannte Propheten, achtzehn davon in 6:83–86. Der Koran sagt, dass es weitere gibt, von denen dem Propheten nicht berichtet wurde (4:164)."],
    ar: ["كم عدد الأنبياء والرسل المذكورين بأسمائهم في القرآن في العدّ المشهور؟", ["خمسة وعشرون", "تسعة عشر", "ثلاثة وثلاثون", "اثنا عشر"], "المشهور أن المذكورين بأسمائهم في القرآن خمسة وعشرون، منهم ثمانية عشر في الأنعام (83–86)، وأخبر القرآن أن هناك رسلًا لم يُقصصوا على النبي ﷺ (النساء 164)."] },

  { id: "aq-055", s: "aqidah", g: 2, d: 3, t: ["messengers", "ulu-al-azm"], src: "Ibn Kathīr, Tafsīr, on 33:7 and 46:35", tr: ["sunni"],
    en: ["Which prophet is commonly counted among the Ulū al-ʿAzm (the messengers of firm resolve)?", ["Nūḥ", "Yūsuf", "Sulaymān", "Yaḥyā"], "The most widespread view counts five as Ulū al-ʿAzm: Nūḥ, Ibrāhīm, Mūsā, ʿĪsā and Muḥammad, who are named together in 33:7 and 42:13."],
    de: ["Welcher Prophet wird gewöhnlich zu den Ulū l-ʿAzm (den Gesandten der Standhaftigkeit) gezählt?", ["Nūḥ", "Yūsuf", "Sulaimān", "Yaḥyā"], "Nach der verbreitetsten Ansicht gehören fünf zu den Ulū l-ʿAzm: Nūḥ, Ibrāhīm, Mūsā, ʿĪsā und Muḥammad, die in 33:7 und 42:13 zusammen genannt werden."],
    ar: ["أيّ الأنبياء يُعدّ في القول المشهور من أولي العزم من الرسل؟", ["نوح", "يوسف", "سليمان", "يحيى"], "المشهور أن أولي العزم خمسة: نوح وإبراهيم وموسى وعيسى ومحمد ﷺ، وقد ذُكروا معًا في الأحزاب (7) والشورى (13)."] },

  { id: "aq-056", s: "aqidah", g: 2, d: 2, t: ["messengers", "isma"], src: "al-Qāḍī ʿIyāḍ, al-Shifā, section on the ʿiṣma of the prophets", tr: ["ijma"],
    en: ["On which aspect of the prophets' protection (ʿiṣma) is there consensus?", ["Protection from error in conveying the message", "Protection from all illness and hardship", "Protection from ever being harmed by enemies", "Protection from forgetting worldly matters"], "Scholars agree that the prophets are protected from lying or erring in conveying what Allah revealed. Prophets did suffer illness, hardship and harm from enemies, which does not contradict their ʿiṣma."],
    de: ["Über welchen Aspekt des Schutzes der Propheten (ʿiṣma) besteht Konsens?", ["Schutz vor Irrtum bei der Übermittlung der Botschaft", "Schutz vor jeder Krankheit und Not", "Schutz davor, je von Feinden verletzt zu werden", "Schutz vor dem Vergessen weltlicher Dinge"], "Die Gelehrten sind sich einig, dass die Propheten davor geschützt sind, bei der Übermittlung der Offenbarung zu lügen oder zu irren. Krankheit, Not und Leid durch Feinde haben sie erfahren; das widerspricht ihrer ʿIṣma nicht."],
    ar: ["في أيّ جانب من عصمة الأنبياء وقع الإجماع؟", ["العصمة من الخطأ في تبليغ الرسالة", "العصمة من كل مرض وشدة", "العصمة من أن يصيبهم أذى الأعداء", "العصمة من نسيان أمور الدنيا"], "أجمع العلماء على عصمة الأنبياء من الكذب والخطأ في تبليغ ما أوحى الله إليهم، وقد أصابهم المرض والشدة وأذى الأعداء ولا ينافي ذلك عصمتهم."] },

  { id: "aq-057", s: "aqidah", g: 2, d: 2, t: ["messengers", "miracles"], src: "Ibn Kathīr, Tafsīr, on 17:88", tr: ["sunni"],
    en: ["What do the scholars regard as the greatest miracle of the Prophet Muḥammad?", ["The Quran", "The splitting of the moon", "Water flowing from his fingers", "The night journey to Jerusalem"], "The Quran is his greatest and lasting miracle, with which he challenged the Arabs to produce anything like it. The other miracles were witnessed at their time; the Quran remains for every generation."],
    de: ["Was sehen die Gelehrten als das größte Wunder des Propheten Muḥammad?", ["Den Koran", "Die Spaltung des Mondes", "Das Wasser, das aus seinen Fingern floss", "Die Nachtreise nach Jerusalem"], "Der Koran ist sein größtes und bleibendes Wunder, mit dem er die Araber herausforderte, Gleiches hervorzubringen. Die anderen Wunder wurden zu ihrer Zeit bezeugt; der Koran bleibt für jede Generation."],
    ar: ["ما الذي يعدّه العلماء أعظم معجزات النبي ﷺ؟", ["القرآن", "انشقاق القمر", "نبع الماء من بين أصابعه", "الإسراء إلى بيت المقدس"], "القرآن أعظم معجزاته الباقية، تحدّى به العرب أن يأتوا بمثله، وسائر المعجزات شوهدت في وقتها، أما القرآن فباقٍ لكل جيل."] },

  { id: "aq-058", s: "aqidah", g: 2, d: 3, t: ["resurrection", "last-day"], src: "Ibn Kathīr, Tafsīr, on 39:68", tr: ["sunni"], v: "39:68",
    en: ["How many blowings of the trumpet are explicitly mentioned in the verse shown?", ["Two: one causing all to swoon, one raising them", "One: the blowing that resurrects", "Three: terror, swoon and resurrection", "Four: one for each corner of the earth"], "The verse mentions a first blowing at which all in the heavens and earth swoon, except whom Allah wills, and then another blowing at which they stand looking on. Some scholars add a blowing of terror from 27:87, but this verse names two."],
    de: ["Wie viele Stöße in das Horn werden im angezeigten Vers ausdrücklich erwähnt?", ["Zwei: einer lässt alle niederstürzen, einer erweckt sie", "Einer: der Stoß der Auferweckung", "Drei: Schrecken, Niederstürzen und Auferstehung", "Vier: einer für jede Ecke der Erde"], "Der Vers erwähnt einen ersten Stoß, bei dem alle in den Himmeln und auf der Erde niederstürzen, außer wen Allah will, und dann einen weiteren, bei dem sie aufstehen und schauen. Manche Gelehrte fügen einen Stoß des Schreckens aus 27:87 hinzu, doch dieser Vers nennt zwei."],
    ar: ["كم نفخة في الصور ذُكرت صراحةً في الآية المعروضة؟", ["نفختان: صعق ثم قيام", "نفخة واحدة هي نفخة البعث", "ثلاث: فزع وصعق وبعث", "أربع: لكل جهة من الأرض نفخة"], "ذكرت الآية نفخة يصعق بها من في السماوات والأرض إلا من شاء الله ثم نفخة أخرى فإذا هم قيام ينظرون، وزاد بعض العلماء نفخة الفزع من سورة النمل (87)، لكن هذه الآية ذكرت اثنتين."] },

  { id: "aq-059", s: "aqidah", g: 2, d: 2, t: ["intercession", "last-day"], src: "al-Bukhārī, al-Ṣaḥīḥ, Kitāb al-Tawḥīd (hadith of the intercession)", tr: ["sunni"],
    en: ["What is \"the great intercession\" (al-shafāʿa al-ʿuẓmā)?", ["The Prophet's intercession for the judgment to begin", "The angels' intercession for children", "The martyrs' intercession for their families", "The Quran's intercession for its reciters"], "In the long hadith of intercession people go from prophet to prophet until they come to Muḥammad, who intercedes for all of creation so that the judgment may begin. Scholars connect this with the Praised Station (17:79), and it is specific to him."],
    de: ["Was ist „die große Fürsprache“ (aš-šafāʿa al-ʿuẓmā)?", ["Die Fürsprache des Propheten, damit das Gericht beginnt", "Die Fürsprache der Engel für die Kinder", "Die Fürsprache der Märtyrer für ihre Familien", "Die Fürsprache des Korans für seine Rezitatoren"], "Im langen Hadith der Fürsprache gehen die Menschen von Prophet zu Prophet, bis sie zu Muḥammad kommen, der für die ganze Schöpfung Fürsprache einlegt, damit das Gericht beginnt. Die Gelehrten verbinden dies mit der gepriesenen Stellung (17:79); sie ist ihm vorbehalten."],
    ar: ["ما الشفاعة العظمى؟", ["شفاعة النبي ﷺ في بدء فصل القضاء", "شفاعة الملائكة في الأطفال", "شفاعة الشهداء في أهليهم", "شفاعة القرآن لأصحابه"], "في حديث الشفاعة الطويل يأتي الناس الأنبياء واحدًا بعد واحد حتى يأتوا محمدًا ﷺ فيشفع للخلق كلهم في فصل القضاء، وهي المقام المحمود (الإسراء 79) وخاصة به."] },

  { id: "aq-060", s: "aqidah", g: 2, d: 3, t: ["intercession", "ayat-al-kursi"], src: "Ibn Abī al-ʿIzz, Sharḥ al-ʿAqīda al-Ṭaḥāwiyya, on intercession", tr: ["sunni"], v: "2:255", w: 23,
    en: ["The highlighted word concerns intercession. Which two conditions do scholars derive from this and related verses (20:109, 53:26)?", ["Allah's permission and His being pleased with the one interceded for", "The intercessor's lineage and the sinner's wealth", "A request in writing and witnesses for it", "The intercessor's presence at the grave and a sacrifice"], "The verse states that none intercedes with Him except by His permission. Combined with verses on His being pleased with the one interceded for, scholars derive two conditions: the permission of Allah and His acceptance of the person concerned."],
    de: ["Das hervorgehobene Wort betrifft die Fürsprache. Welche zwei Bedingungen leiten die Gelehrten aus diesem und verwandten Versen (20:109, 53:26) ab?", ["Allahs Erlaubnis und Sein Wohlgefallen an dem, für den Fürsprache eingelegt wird", "Die Abstammung des Fürsprechers und das Vermögen des Sünders", "Eine schriftliche Bitte und Zeugen dafür", "Anwesenheit des Fürsprechers am Grab und ein Opfer"], "Der Vers sagt, dass niemand bei Ihm Fürsprache einlegt außer mit Seiner Erlaubnis. Zusammen mit den Versen über Sein Wohlgefallen an dem Betreffenden leiten die Gelehrten zwei Bedingungen ab: Allahs Erlaubnis und Seine Zustimmung zur betreffenden Person."],
    ar: ["الكلمة المظللة في شأن الشفاعة، فما الشرطان اللذان يستنبطهما العلماء منها ومن آيات أخرى (طه 109، النجم 26)؟", ["إذن الله ورضاه عن المشفوع له", "نسب الشافع ومال المذنب", "طلب مكتوب وشهود عليه", "حضور الشافع عند القبر وذبيحة"], "تقرر الآية أنه لا يشفع أحد عنده إلا بإذنه، ومع الآيات في رضاه عن المشفوع له استنبط العلماء شرطين: إذن الله للشافع ورضاه عن المشفوع له."] },

  { id: "aq-061", s: "aqidah", g: 2, d: 2, t: ["paradise-and-hell", "seeing-allah"], src: "Ibn Kathīr, Tafsīr, on 75:22–23", tr: ["sunni"], v: "75:23",
    en: ["Ahl al-Sunna cite the verse shown (with the one before it) as proof of what?", ["That the believers will see their Lord in the Hereafter", "That Paradise has eight gates", "That the righteous will intercede", "That the sun will be brought near"], "The verses describe radiant faces looking at their Lord. Together with mass-transmitted hadith, Ahl al-Sunna across the Atharī, Ashʿarī and Māturīdī schools affirm that the believers will see Allah in the Hereafter."],
    de: ["Als Beleg wofür führen Ahl as-Sunna den angezeigten Vers (mit dem vorangehenden) an?", ["Dass die Gläubigen ihren Herrn im Jenseits sehen werden", "Dass das Paradies acht Tore hat", "Dass die Rechtschaffenen Fürsprache einlegen", "Dass die Sonne nahe gebracht wird"], "Die Verse beschreiben strahlende Gesichter, die zu ihrem Herrn schauen. Zusammen mit massenhaft überlieferten Hadithen bekräftigen Ahl as-Sunna in der atharitischen, ašʿaritischen und māturīditischen Schule, dass die Gläubigen Allah im Jenseits sehen werden."],
    ar: ["بمَ يستدل أهل السنة بالآية المعروضة مع التي قبلها؟", ["على رؤية المؤمنين ربهم في الآخرة", "على أن للجنة ثمانية أبواب", "على شفاعة الصالحين", "على دنو الشمس من الخلائق"], "تصف الآيتان وجوهًا ناضرة إلى ربها ناظرة، ومع الأحاديث المتواترة أثبت أهل السنة من الأثرية والأشاعرة والماتريدية رؤية المؤمنين ربهم في الآخرة."] },

  { id: "aq-062", s: "aqidah", g: 2, d: 3, t: ["paradise-and-hell", "last-day"], src: "Ibn Kathīr, Tafsīr, on 7:46–49", tr: ["sunni"],
    en: ["The people standing on the heights between Paradise and Hell give their name to which sūra?", ["Al-Aʿrāf", "Al-Ḥadīd", "Al-Ḥijr", "Al-Burūj"], "Sūrat al-Aʿrāf (7:46–49) describes people on the heights of the partition between the two abodes; many scholars explain them as those whose good and bad deeds are equal, who will eventually enter Paradise."],
    de: ["Die Menschen, die auf den Höhen zwischen Paradies und Hölle stehen, geben welcher Sure ihren Namen?", ["Al-Aʿrāf", "Al-Ḥadīd", "Al-Ḥiǧr", "Al-Burūǧ"], "Sūrat al-Aʿrāf (7:46–49) beschreibt Menschen auf den Höhen der Trennwand zwischen den beiden Wohnstätten; viele Gelehrte erklären sie als jene, deren gute und schlechte Taten gleich sind und die schließlich ins Paradies eingehen."],
    ar: ["أهل المكان المرتفع بين الجنة والنار سُمّيت باسمهم أيّ سورة؟", ["الأعراف", "الحديد", "الحجر", "البروج"], "وصفت سورة الأعراف (46–49) رجالًا على أعراف الحجاب بين الدارين، وكثير من العلماء على أنهم من استوت حسناتهم وسيئاتهم ثم يدخلون الجنة."] },

  { id: "aq-063", s: "aqidah", g: 2, d: 3, t: ["iman-increase", "iman-definition"], src: "Ibn Kathīr, Tafsīr, on 8:2", tr: ["sunni"], v: "8:2", w: 13,
    en: ["What does the highlighted verb state happens to the believers when Allah's verses are recited to them?", ["Their faith is increased", "Their sins are erased", "Their hearts become hard", "Their reward is doubled"], "The verse says that the recitation of His verses increases them in faith. Scholars who hold that īmān increases and decreases cite this verse, together with 48:4 and others."],
    de: ["Was geschieht laut dem hervorgehobenen Verb mit den Gläubigen, wenn ihnen Allahs Verse vorgetragen werden?", ["Ihr Glaube wird gemehrt", "Ihre Sünden werden getilgt", "Ihre Herzen verhärten sich", "Ihr Lohn wird verdoppelt"], "Der Vers sagt, dass das Vortragen Seiner Verse ihren Glauben mehrt. Gelehrte, die lehren, dass der Īmān zu- und abnimmt, führen diesen Vers zusammen mit 48:4 und anderen an."],
    ar: ["ماذا يحدث للمؤمنين إذا تُليت عليهم آيات الله بحسب الفعل المظلل؟", ["يزدادون إيمانًا", "تُمحى سيئاتهم", "تقسو قلوبهم", "يُضاعف أجرهم"], "تذكر الآية أن تلاوة آياته تزيدهم إيمانًا، ويستدل بها مع آية الفتح (4) وغيرها من قال بزيادة الإيمان ونقصانه."] },

  { id: "aq-064", s: "aqidah", g: 2, d: 2, t: ["divine-speech", "creeds-and-authors"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Aḥmad ibn Ḥanbal", tr: ["sunni"],
    en: ["Which imam is famous for his steadfastness during the Miḥna over the claim that the Quran is created?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "Sufyān al-Thawrī"], "Aḥmad ibn Ḥanbal refused under imprisonment and flogging to say that the Quran is created, affirming that it is the uncreated speech of Allah. Mālik, Abū Ḥanīfa and Sufyān al-Thawrī had died before the Miḥna."],
    de: ["Welcher Imam ist für seine Standhaftigkeit während der Miḥna um die Behauptung, der Koran sei erschaffen, berühmt?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "Sufyān aṯ-Ṯaurī"], "Aḥmad ibn Ḥanbal weigerte sich trotz Haft und Auspeitschung zu sagen, der Koran sei erschaffen, und bekräftigte, dass er die unerschaffene Rede Allahs ist. Mālik, Abū Ḥanīfa und Sufyān aṯ-Ṯaurī waren vor der Miḥna gestorben."],
    ar: ["أيّ الأئمة اشتهر بثباته في المحنة في القول بخلق القرآن؟", ["أحمد بن حنبل", "مالك بن أنس", "أبو حنيفة", "سفيان الثوري"], "رفض الإمام أحمد مع السجن والضرب أن يقول بخلق القرآن، وأثبت أنه كلام الله غير مخلوق، أما مالك وأبو حنيفة والثوري فتوفّوا قبل المحنة."] },

];
